    justifyContent: 'center',
    cursor: 'pointer'
  },
  modalActions: {
    display: 'flex',
    justifyContent: 'flex-end',
    gap: '12px',
    marginTop: '12px'
  },
  cancelBtn: {
    padding: '10px 16px',
    borderRadius: '8px',
    border: 'none',
    backgroundColor: '#3f3f46',
    color: '#ffffff',
    fontWeight: '600',
    cursor: 'pointer'
  },
  submitModalBtn: {
    padding: '10px 18px',
    borderRadius: '8px',
    border: 'none',
    backgroundColor: '#ea580c',
    color: '#ffffff',
    fontWeight: '600',
    cursor: 'pointer'
  }
};
var _c;
$RefreshReg$(_c, "Admin");

